<main id="main">
  <section id="view-overview">
    <h1>Overview</h1>
    <p>Placeholder view. Replace with your product content.</p>
    <div class="hint"><span>Open the command palette with</span> <kbd class="mod">Ctrl</kbd><kbd>K</kbd></div>
  </section>
  <section id="view-projects" hidden><h1>Projects</h1><p>Placeholder view.</p></section>
  <section id="view-reports" hidden><h1>Reports</h1><p>Placeholder view.</p></section>
