</main>

<dialog class="palette" id="palette" aria-label="Command menu">
  <div class="palette-search">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>
    <input id="q" type="text" role="combobox" autocomplete="off" spellcheck="false"
           placeholder="Type a command or search…" aria-label="Search commands"
           aria-expanded="true" aria-controls="results" aria-autocomplete="list">
    <kbd>Esc</kbd>
  </div>

  <ul class="palette-list" id="results" role="listbox" aria-label="Commands"></ul>

  <div class="palette-empty" id="empty" hidden>
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5M8.5 8.5l5 5m0-5-5 5"/></svg>
