    <span><kbd>↑</kbd><kbd>↓</kbd> Navigate</span>
    <span><kbd>Enter</kbd> Select</span>
    <span><kbd>Esc</kbd> Close</span>
  </div>
  <div class="sr-only" id="live" role="status" aria-live="polite"></div>
</dialog>

<script>
(function () {
  var $ = function (id) { return document.getElementById(id); };
  var dlg = $("palette"), q = $("q"), list = $("results"), empty = $("empty");
  var emptyMsg = $("emptyMsg"), live = $("live"), trigger = $("openPalette");
  var root = document.documentElement;
  var isMac = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
  var modName = isMac ? "⌘" : "Ctrl";
  var lastFocus = null, active = 0, shown = [];

  // Platform-correct shortcut hints
  $("triggerKbd").textContent = modName + " K";
  document.querySelectorAll("kbd.mod").forEach(function (k) { k.textContent = modName; });

  // Commands (placeholders: replace with real app actions)
  var commands = [
    { label: "Go to Overview", hint: "Page",   words: "home dashboard", run: function () { location.hash = "#overview"; } },
    { label: "Go to Projects", hint: "Page",   words: "work",           run: function () { location.hash = "#projects"; } },
    { label: "Go to Reports",  hint: "Page",   words: "analytics",      run: function () { location.hash = "#reports"; } },
    { label: "Go to Settings", hint: "Page",   words: "preferences",    run: function () { location.hash = "#settings"; } },
    { label: "Toggle theme",   hint: "Action", words: "dark light mode", run: toggleTheme }
  ];

  /* ---------- Palette ---------- */
  function render() {
    var term = q.value.trim().toLowerCase();
    shown = commands.filter(function (c) {
      return !term || (c.label + " " + c.words).toLowerCase().indexOf(term) !== -1;
    });
    list.textContent = "";
    shown.forEach(function (c, i) {
      var li = document.createElement("li");
      li.id = "cmd-" + i;
      li.setAttribute("role", "option");
      var a = document.createElement("span"); a.textContent = c.label;
      var b = document.createElement("small"); b.textContent = c.hint;
      li.append(a, b);
      li.addEventListener("pointermove", function () { if (active !== i) setActive(i); });
      li.addEventListener("click", function () { run(i); });
      list.appendChild(li);
    });
    var none = shown.length === 0;
    list.hidden = none;
    empty.hidden = !none;
    if (none) {
      emptyMsg.textContent = 'No matching commands for "' + q.value.trim() + '"';
      q.removeAttribute("aria-activedescendant");
    }
    live.textContent = none ? "No results" : shown.length + (shown.length === 1 ? " result" : " results");
    setActive(0);
  }

  function setActive(i) {
    if (!shown.length) return;
    active = (i + shown.length) % shown.length;
    Array.prototype.forEach.call(list.children, function (li, n) {
      li.setAttribute("aria-selected", n === active ? "true" : "false");
    });
    var el = list.children[active];
    q.setAttribute("aria-activedescendant", el.id);
    el.scrollIntoView({ block: "nearest" });
  }

  function run(i) {
    var c = shown[i];
    if (!c) return;
    dlg.close();
    c.run();
  }

  function openPalette() {
    if (dlg.open) return;
    lastFocus = document.activeElement;
    q.value = "";
    render();
    dlg.showModal();
    q.focus();
  }

  function reset() { q.value = ""; render(); q.focus(); }

  q.addEventListener("input", render);
  q.addEventListener("keydown", function (e) {
    if (e.key === "ArrowDown") { e.preventDefault(); setActive(active + 1); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setActive(active - 1); }
    else if (e.key === "Home") { e.preventDefault(); setActive(0); }
    else if (e.key === "End") { e.preventDefault(); setActive(shown.length - 1); }
    else if (e.key === "Enter") { e.preventDefault(); run(active); }
  });
  $("resetBtn").addEventListener("click", reset);
  dlg.addEventListener("click", function (e) { if (e.target === dlg) dlg.close(); }); // backdrop
  dlg.addEventListener("close", function () {
    if (lastFocus && document.contains(lastFocus)) lastFocus.focus();
  });
  trigger.addEventListener("click", openPalette);

  document.addEventListener("keydown", function (e) {
    if ((e.ctrlKey || e.metaKey) && !e.altKey && e.key.toLowerCase() === "k") {
      e.preventDefault();
      dlg.open ? dlg.close() : openPalette();
    }
  });
  // Escape is handled natively by <dialog> (fires "close", focus returns to the trigger).

  /* ---------- Navigation ---------- */
  var links = document.querySelectorAll("#navLinks a, #drawer a");
  var indicator = $("indicator"), navLinks = $("navLinks");
  var menuBtn = $("menuBtn"), drawer = $("drawer");

  function route() {
    var id = (location.hash || "#overview").slice(1);
    if (!$("view-" + id)) id = "overview";
    document.querySelectorAll("main section").forEach(function (s) { s.hidden = s.id !== "view-" + id; });
    links.forEach(function (a) {
      if (a.getAttribute("href") === "#" + id) a.setAttribute("aria-current", "page");
      else a.removeAttribute("aria-current");
    });
    moveIndicator();
    closeDrawer();
  }
  function moveIndicator() {
    var a = navLinks.querySelector('[aria-current="page"]');
    if (!a || !navLinks.offsetWidth) { indicator.style.width = "0"; return; }
    indicator.style.width = a.offsetWidth + "px";
    indicator.style.transform = "translateX(" + a.offsetLeft + "px)";
  }
  function closeDrawer() {
    drawer.hidden = true;
    menuBtn.setAttribute("aria-expanded", "false");
  }
  menuBtn.addEventListener("click", function () {
    var open = drawer.hidden;
    drawer.hidden = !open;
    menuBtn.setAttribute("aria-expanded", String(open));
  });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && !drawer.hidden && !dlg.open) { closeDrawer(); menuBtn.focus(); }
  });
  window.addEventListener("hashchange", route);
  window.addEventListener("resize", function () { moveIndicator(); if (innerWidth >= 768) closeDrawer(); });

  // Glass appears after scrolling past 8px
  var wrap = $("navWrap");
  function onScroll() { wrap.dataset.scrolled = String(scrollY > 8); }
  addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- Theme ---------- */
  function toggleTheme() {
    var dark = root.dataset.theme
      ? root.dataset.theme === "dark"
      : matchMedia("(prefers-color-scheme: dark)").matches;
    root.dataset.theme = dark ? "light" : "dark";
  }
  $("themeBtn").addEventListener("click", toggleTheme);

  route();
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(moveIndicator);
})();
</script>
</body>
</html>
```

**States and keyboard behavior**
- **Open and close:** `Ctrl+K` or `⌘K` toggles the palette from anywhere, and the trigger button opens it too. The hint shows `⌘ K` on Apple platforms and `Ctrl K` elsewhere.
- **Close:** `Escape` is handled by the native `<dialog>`. Clicking the backdrop also closes it. Focus returns to the element that opened it.
- **Selection:** `↓` and `↑` move the selected row and wrap around. `Home` and `End` jump to the first and last row. `Enter` runs the selected command. Hovering a row selects it, and clicking runs it.
- **Visible hints:** the trigger shows `<kbd>`, the palette footer shows `↑ ↓`, `Enter` and `Esc`, and the Overview page shows the open shortcut.
- **Empty search:** it shows `No matching commands for "…"` and a 44px **Clear search** button. The button empties the field, restores the full list and refocuses the input. A polite live region announces the result count.
- **Other states:** the nav has hover, `:focus-visible` (2px outline), `aria-current` with a sliding pill, and a disabled style. Under 768px the links move into a menu drawer that closes on `Escape` or when you navigate.
- **Reduced motion:** transitions and animations are turned off.
- **Not included:** the loading skeleton and the error with retry. The palette filters a local list, so neither can occur. Add them once the commands come from a network source.

**Accessibility and visual check**
- I did not run this in a browser, so there are no 1440px or 390px screenshots, console-error checks or measured contrast ratios. That is still to do.
- By construction, the muted text pairs use the reference tokens, which are documented as at least 7:1. The 2px focus outline and the borders use tokens that should reach 3:1.
- The layout uses `box-sizing`, `overflow-x: hidden` on the body, and a `min(560px, 100vw - 32px)` dialog, so it should not overflow at 390px.

